import{_ as r,C as a,o,c,a2 as e,b as i,w as d,a as n,E as l,a3 as u}from"./chunks/framework.BaXgE4DV.js";const b=JSON.parse('{"title":"질문으로 쓰기","description":"","frontmatter":{},"headers":[],"relativePath":"features/guided-writing.md","filePath":"features/guided-writing.md","lastUpdated":1792481551000}'),q={name:"features/guided-writing.md"};function h(p,t,g,E,A,f){const s=a("Mermaid");return o(),c("div",null,[t[1]||(t[1]=e('<h1 id="guided-writing" tabindex="-1">질문으로 쓰기 <a class="header-anchor" href="#guided-writing" aria-label="Permalink to &quot;질문으로 쓰기 {#guided-writing}&quot;">​</a></h1><p>&quot;질문으로 쓰기&quot;는 무엇을 써야 할지 모를 때 질문에 답하며 감사 글을 시작하는 작성 모드입니다. 쓰기 화면(직접 작성)의 저장 버튼 아래 카드에 질문이 보이고, <strong>[이 질문으로 감사 적기]</strong> 를 누르면 그 질문으로 시작합니다. 위젯의 질문을 눌러도 그 질문으로 바로 열립니다. 질문은 운영자가 선정한 질문(기본 질문 + 사용자가 제안해 선정된 질문)에서 고릅니다. 답변과 초안 만들기는 모두 <strong>기기 안에서</strong> 이루어지고, 작성 내용은 사용자가 저장할 때 일반 글 저장 경로로만 Firestore에 올라갑니다. → <a href="/grato-docs/decisions#adr-10">결정 기록 #10</a>, <a href="/grato-docs/decisions#adr-11">#11</a></p><h2 id="흐름" tabindex="-1">흐름 <a class="header-anchor" href="#흐름" aria-label="Permalink to &quot;흐름&quot;">​</a></h2>',3)),(o(),i(u,null,{default:d(()=>[l(s,{id:"mermaid-9",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20U%20as%20%EC%82%AC%EC%9A%A9%EC%9E%90%0A%20%20participant%20W%20as%20WritePage%20(GuidedMode)%0A%20%20participant%20A%20as%20src%2Flib%2FquestionApi.js%0A%20%20participant%20Q%20as%20src%2Fcontent%2Fquestions.js%0A%20%20participant%20F%20as%20Firestore%0A%20%20W-%3E%3EA%3A%20loadQuestionPools()%20(%EC%84%B8%EC%85%98%EC%97%90%20%ED%95%9C%20%EB%B2%88)%0A%20%20A-%3E%3EF%3A%20questions%20where%20status%20%3D%3D%20approved%2C%20limit%20500%0A%20%20F--%3E%3EA%3A%20%EC%84%A0%EC%A0%95%EB%90%9C%20%EC%A7%88%EB%AC%B8%0A%20%20A-%3E%3EQ%3A%20buildQuestionPools(%EC%84%A0%EC%A0%95%EB%90%9C%20%EC%A7%88%EB%AC%B8)%0A%20%20Q--%3E%3EW%3A%20%7B%20opening%2C%20followup%20%7D%0A%20%20W-%3E%3EQ%3A%20pickQuestion(opening)%0A%20%20U-%3E%3EW%3A%20%EB%8B%B5%EB%B3%80%201%0A%20%20W-%3E%3EQ%3A%20pickQuestion(followup)%0A%20%20alt%20%EB%8B%B5%EB%B3%80%ED%95%A8%0A%20%20%20%20U-%3E%3EW%3A%20%EB%8B%B5%EB%B3%80%202%0A%20%20else%20%EA%B1%B4%EB%84%88%EB%9C%80%0A%20%20%20%20U-%3E%3EW%3A%20%22%EC%9D%B4%20%EC%A7%88%EB%AC%B8%EC%9D%80%20%EA%B1%B4%EB%84%88%EB%9B%B8%EA%B2%8C%EC%9A%94%22%0A%20%20end%0A%20%20W-%3E%3EQ%3A%20buildDraftContent(%5B%EB%8B%B5%EB%B3%80%201%2C%20%EB%8B%B5%EB%B3%80%202%5D)%0A%20%20U-%3E%3EW%3A%20%EC%A0%9C%EB%AA%A9%20%EC%9E%85%EB%A0%A5%2C%20%EB%82%B4%EC%9A%A9%20%EC%88%98%EC%A0%95%2C%20%EA%B3%B5%EA%B0%9C%20%EB%B2%94%EC%9C%84%20%EC%84%A0%ED%83%9D%0A%20%20W-%3E%3EF%3A%20createGratitude%20(%EC%A7%81%EC%A0%91%20%EC%9E%91%EC%84%B1%EA%B3%BC%20%EA%B0%99%EC%9D%80%20%EA%B2%BD%EB%A1%9C)%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<ol><li><strong>첫 번째 질문</strong> — 쓰기 화면 카드에서 고른 질문입니다. 카드는 처음에 오늘의 질문(<code>todayQuestion</code>: 시즌 날에는 시즌 질문, 그 밖에는 <a href="#facets">요일별 결</a>에서 하나 — 홈 화면 위젯과 같은 질문)을 보여 주고, &quot;다른 질문&quot;을 누르면 무작위로 바꿉니다. 답을 써야 다음으로 넘어갑니다.</li><li><strong>두 번째 질문</strong> — 이어지는 질문 풀에서 하나를 보여 줍니다. 답하거나 &quot;이 질문은 건너뛸게요&quot;로 바로 초안을 만들 수 있습니다.</li><li><strong>초안</strong> — 답변을 빈 줄로 이어 붙여 내용에 넣고, 제목은 비워 둡니다.</li><li><strong>저장</strong> — 첫 질문의 ID가 있으면 글에 <code>questionId</code>로 함께 남습니다(내용은 질문과 상관없이 내 글 그대로, → <a href="/grato-docs/features/questions#answers">내 질문으로 쓰인 감사</a>). 제목과 내용이 모두 있어야 저장 버튼이 켜집니다. 공개 범위는 기본이 &quot;나만 보기&quot;이고(버튼 &quot;저장하기&quot;), &quot;Circle에 공유&quot;를 고르면 Circle을 골라야 저장할 수 있습니다(버튼 &quot;Circle에 공유하기&quot;). → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a></li></ol><p>질문 카드의 &quot;다른 질문&quot;을 누르면 같은 풀에서 지금 질문과 다른 질문으로 바꿉니다. 사용자가 제안해 선정된 질문에는 &quot;💡 홍길동 #1234님의 질문&quot;처럼 제안자의 공개 이름이 함께 보입니다(기본 질문이나 이름이 없는 질문은 표시하지 않음). → <a href="/grato-docs/features/questions#credit">제안자 표시</a></p><p>첫 번째 질문 카드 아래에는 <strong>[이 질문 추천]</strong> 과 <strong>&quot;추천 많은 질문&quot;</strong>(추천받은 질문을 많은 순으로 모은 시트, 골라서 바로 쓰기)이 있습니다. → <a href="/grato-docs/features/questions#recommends">질문 추천</a></p><p>질문 화면 아래의 &quot;좋은 질문이 떠올랐나요? 질문 제안하기&quot;로 질문을 제안할 수 있습니다. → <a href="/grato-docs/features/questions">질문 제안과 선정</a></p><h2 id="pools" tabindex="-1">질문 풀 <a class="header-anchor" href="#pools" aria-label="Permalink to &quot;질문 풀 {#pools}&quot;">​</a></h2><p>질문은 <strong>운영자가 선정한 질문</strong>에서 고르고, 그것을 읽지 못하면 앱에 들어 있는 기본 질문 목록으로 대신합니다.</p><table tabindex="0"><thead><tr><th>출처</th><th>위치</th><th>설명</th></tr></thead><tbody><tr><td>선정된 질문</td><td><code>questions</code> (<code>status == &quot;approved&quot;</code>)</td><td>기본 질문(<code>source: &quot;system&quot;</code>) + 사용자가 제안해 선정된 질문(<code>source: &quot;user&quot;</code>)</td></tr><tr><td>앱 안의 기본 질문</td><td><code>src/content/questions.json</code></td><td><code>{ &quot;opening&quot;: [{text, facet} 45개], &quot;followup&quot;: [10개], &quot;seasons&quot;: [...] }</code>. <code>seedQuestions</code> 스크립트가 같은 파일을 Firestore의 <code>system_*</code> 문서로 넣음. <code>seasons</code>는 <a href="#season-questions">시즌 질문</a></td></tr></tbody></table><p><code>src/lib/questionApi.js</code>의 <code>loadQuestionPools()</code>가 풀을 만듭니다.</p><ul><li>선정된 질문을 <strong>세션에 한 번</strong> 읽습니다(<code>where(&#39;status&#39;, &#39;==&#39;, &#39;approved&#39;)</code>, 최대 500개, 정렬 없음). 그래서 새로 선정된 질문은 다음에 앱을 열 때부터 나옵니다.</li><li>읽기에 실패했거나 오프라인 캐시에서 온 결과는 저장하지 않아 다음에 다시 읽습니다. 4초 안에 오지 않으면 앱 안의 목록으로 먼저 시작합니다.</li><li><code>buildQuestionPools()</code>가 종류(<code>kind</code>)별로 나눕니다. 어떤 종류에 선정된 <strong>기본</strong> 질문(시즌 질문 제외)이 하나도 없으면(시드 전, 읽기 실패) <code>questions.json</code>의 목록에 선정된 사용자 질문을 더해 씁니다. 사용자 질문 몇 개가 기본 질문 전체를 대신하지 않게 하기 위해서입니다.</li><li>같은 문구(공백·구두점·보이지 않는 문자를 빼고 같은 것)는 한 번만 넣습니다.</li><li>숨긴 질문(<code>hidden</code>)은 풀에 들어가지 않습니다.</li></ul><p><code>src/content/questions.js</code>는 JSON을 import할 뿐 React·Firebase를 import하지 않는 순수 모듈이라 <code>node:test</code>로 바로 테스트합니다(<code>questions.test.js</code>).</p><table tabindex="0"><thead><tr><th>함수</th><th>동작</th></tr></thead><tbody><tr><td><code>buildQuestionPools(approved)</code></td><td>선정된 질문을 <code>{ opening, followup }</code>으로 나눔 (위의 대체 규칙 포함)</td></tr><tr><td><code>pickQuestion(pool, exclude?)</code></td><td>풀에서 무작위로 하나. <code>exclude</code>(지금 보이는 질문)는 다른 선택지가 있으면 고르지 않음</td></tr><tr><td><code>todayQuestion(pool, now?)</code>, <code>questionForDay(pool, day)</code></td><td>오늘(KST)의 질문. 시즌 날에는 그날의 <a href="#season-questions">시즌 질문</a>, 그 밖에는 <a href="#facets">그날 요일의 결</a>에서 주마다 하나씩 — 모두에게 같은 날 같은 질문(시드된 시즌 질문은 이 순환에서 빠짐). 위젯(<code>widgetModel.dailyQuestions</code>)도 같은 함수</td></tr><tr><td><code>facetOfDay(day)</code>, <code>questionFacet(question)</code></td><td>그날의 결, 질문의 결(문서의 <code>facet</code>, 없으면 앱 안 기본 질문의 결을 문구로 찾음. 시즌·결 없는 사용자 질문은 null). 분석 <code>facet</code>에도 씀</td></tr><tr><td><code>findQuestion(pool, wanted, now?)</code></td><td>위젯 링크·카드에서 넘어온 질문(id 또는 문구)을 풀에서 찾음. 지금 진행 중인 시즌의 질문은 시드 전이면 앱 안 사본으로</td></tr><tr><td><code>followupsFor(opening, followupPool)</code></td><td>이어지는 질문 후보. 한 해 돌아보기 질문이면 시즌의 이어지는 질문 3개, 아니면 풀</td></tr><tr><td><code>topRecommendedQuestions(pool, limit?)</code>, <code>canRecommend(question, uid)</code></td><td>추천 많은 질문(추천 수 많은 순, 10개), 추천할 수 있는지(ID 있음, 내 질문 아님) — <a href="/grato-docs/features/questions#recommends">질문 추천</a></td></tr><tr><td><code>questionSeasonKey(question)</code></td><td>시즌 질문이면 <code>seasonKey</code>(분석용), 아니면 null</td></tr><tr><td><code>buildDraftContent(answers)</code></td><td>답변의 앞뒤 공백을 지우고, 빈 답변을 빼고, 빈 줄(<code>\\n\\n</code>)로 이어 붙임</td></tr><tr><td><code>questionCredit(question)</code></td><td>사용자 질문의 &quot;💡 {이름}님의 질문&quot; 문구</td></tr><tr><td><code>normalizeQuestionText</code>, <code>questionTextError</code></td><td>서버와 같은 정규화와 5~80자 확인 (질문 제안·운영자 수정에 사용)</td></tr><tr><td><code>QUESTION_POOL</code>, <code>FOLLOWUP_POOL</code></td><td><code>questions.json</code>의 <code>opening</code> 문구, <code>followup</code> (따로 복사해 두지 않음)</td></tr><tr><td><code>QUESTION_FACETS</code>, <code>FACET_LABELS</code></td><td>결 7개와 이름(함수 <code>functions/src/questions/text.ts</code>와 같게)</td></tr></tbody></table><p>기본 질문을 추가·수정할 때는 <code>questions.json</code>을 고치고, 배포 때 <code>seedQuestions</code>를 실행합니다. 첫 질문은 맨 뒤에 더하고(문서 ID가 순서로 정해짐) <code>facet</code>을 붙입니다. 이어지는 질문은 첫 질문과 상관없이 고르므로 어떤 첫 질문 뒤에 와도 자연스러운 문장으로 씁니다. → <a href="/grato-docs/features/questions#system-questions">기본 질문</a></p><h2 id="facets" tabindex="-1">오늘의 질문: 요일별 결 <a class="header-anchor" href="#facets" aria-label="Permalink to &quot;오늘의 질문: 요일별 결 {#facets}&quot;">​</a></h2><p>시즌 밖(시즌 질문이 없는 날)의 오늘의 질문은 <strong>요일마다 정한 결</strong>에서 고릅니다(GRATO-93). 모두의 감사방 <a href="/grato-docs/features/circles#daily-topic">오늘의 주제</a>와 같은 요일 표라 하루의 결이 한 가지로 맞지만, 문장은 서로 다르게 씁니다. → <a href="/grato-docs/decisions#adr-43">ADR-43</a></p><table tabindex="0"><thead><tr><th>요일</th><th>결 (<code>facet</code>)</th><th>묻는 것</th></tr></thead><tbody><tr><td>월</td><td>작은 것 <code>small</code></td><td>일상 속 작은 즐거움, 장소, 감각</td></tr><tr><td>화</td><td>사람 <code>people</code></td><td>곁의 사람, 받은 친절, 대화</td></tr><tr><td>수</td><td>없었다면 <code>absence</code></td><td>좋은 일·만남·장소가 없었다면 (사람을 잃는 장면은 묻지 않음)</td></tr><tr><td>목</td><td>특정 순간 <code>moment</code></td><td>장면 하나</td></tr><tr><td>금</td><td>고마움 잇기 <code>forward</code></td><td>고마움을 알려 주기, 건네기 (&quot;갚기&quot;가 아님)</td></tr><tr><td>토</td><td>섞인 감정 <code>mixed</code></td><td>힘들었지만 고마운 것</td></tr><tr><td>일</td><td>한 주 돌아보기 <code>reflect</code></td><td>한 주·하루 정리</td></tr></tbody></table><p>고르는 규칙(<code>questionForDay</code>, KST 날짜):</p><ol><li>그날이 시즌이면 그날의 <a href="#season-questions">시즌 질문</a>. 끝.</li><li>요일 → 결.</li><li>그 결의 질문 목록(<code>facet</code>이 그 결이고 시즌 질문이 아닌 것, <code>order</code> 순)에서 <strong>주 번호(월요일 시작) % 목록 길이</strong>. 같은 결의 질문은 목록을 다 돌기 전에 다시 나오지 않습니다(결마다 6–9주에 한 번).</li><li>목록: 기본 질문은 <code>questions.json</code> 순서(<code>order</code> = 0부터의 위치), 결을 고른 사용자 질문은 그 뒤에 선정한 순서(<code>order</code> = 처음 결을 정해 선정한 시각, ms).</li><li>시드 전이라 문서에 <code>facet</code>이 없으면 앱 안 기본 질문의 결·순서를 문구로 찾아 씁니다. 그래서 읽기 실패·시드 전에도 같은 날 같은 질문입니다.</li><li>그 결의 질문이 하나도 없으면(운영자가 모두 숨김) 예전처럼 풀 전체를 하루 하나씩 돕니다.</li></ol><ul><li>운영자가 사용자 질문을 선정할 때 결을 고르면 그 결의 순환에 들어갑니다. 고르지 않으면 순환에는 안 들어가고 &quot;다른 질문&quot;에만 나옵니다. 그래서 질문 하나가 선정돼도 <strong>다른 결의 날은 바뀌지 않습니다</strong>(같은 결의 날만 목록 길이가 바뀜). → <a href="/grato-docs/features/questions#review">선정 화면</a></li><li>&quot;다른 질문&quot;은 지금처럼 풀 전체(결·시즌 상관없음)에서 무작위입니다. 한 줄만 써도 기록이 됩니다.</li><li>위젯의 7일 치도 같은 함수라, 시즌 경계(11/14→11/15, 1/10→1/11)가 섞여도 쓰기 화면과 같습니다. Swift·Java 위젯은 받은 문장을 보여 주기만 해 바뀌지 않습니다.</li><li>카드뉴스(월·수·금)는 이 결을 따르지 않고 지금처럼 주 단위로 돕니다. → <a href="/grato-docs/operations/card-news">카드뉴스</a></li><li>분석: 질문으로 쓰기의 <code>gratitude_started</code>·<code>gratitude_created</code>에 <code>facet</code>(결 이름만, 문구 없음)이 붙습니다.</li><li>1.0.1 (6) 이하 앱은 예전처럼 문서 순서로 하루 하나씩 돕니다. 새 기본 질문 15개가 풀에 들어가 순서가 바뀔 뿐 깨지지 않습니다.</li></ul><h2 id="season-questions" tabindex="-1">시즌 질문 <a class="header-anchor" href="#season-questions" aria-label="Permalink to &quot;시즌 질문 {#season-questions}&quot;">​</a></h2><p>연말연초 시즌(GRATO-66)에는 그날의 질문(쓰기 화면 아래 카드, 홈 화면 위젯, 카드뉴스)이 <strong>날짜로 정해진 시즌 질문</strong>입니다. 서버가 날마다 바꾸지 않고, 앱이 KST 날짜로 계산합니다.</p><table tabindex="0"><thead><tr><th>시즌 (<code>seasonKey</code>)</th><th>날짜 (KST)</th><th>그날의 질문</th></tr></thead><tbody><tr><td>감사의 계절 (<code>2026-thanks</code>)</td><td>11/15–11/22</td><td>감사의 계절 질문 T1–T8</td></tr><tr><td></td><td>11/23–11/30</td><td>T1–T8을 다시</td></tr><tr><td>한 해 돌아보기 (<code>2026-winter</code>)</td><td>12/1–12/21</td><td>연말 질문 1–21번을 날짜 순서로</td></tr><tr><td></td><td>12/22–12/27</td><td>1–6번을 다시</td></tr><tr><td></td><td>12/28–12/31</td><td>마무리 질문 4개(M1–M4)</td></tr><tr><td>신년 감사 (<code>2027-newyear</code>)</td><td>1/1–1/10</td><td>신년 질문 1–10번</td></tr><tr><td>—</td><td>1/11–11/14</td><td>기본 순환</td></tr></tbody></table><ul><li><strong>데이터</strong>: <code>questions.json</code>의 <code>seasons</code>(<code>seasonKey</code>, <code>name</code>, <code>start</code>, 하루 하나씩의 <code>days</code>, <code>opening</code>·<code>followup</code> 문구, 다른 시즌의 이어지는 질문을 쓸 때 <code>followupFrom</code>). 계산은 순수 모듈 <code>src/content/seasonQuestions.js</code>. 문서 ID는 <code>system_season_{seasonKey}_{키}</code>(예: <code>system_season_2026-winter_01</code>, 감사의 계절 <code>system_season_2026-thanks_t1</code>, 마무리 <code>_m1</code>, 이어지는 질문 <code>_f1</code>).</li><li><strong>앱 안 사본</strong>: 시드 전이나 질문을 읽지 못해도 앱에 든 사본으로 나옵니다. 시드된 뒤에는 Firestore 문서(같은 ID)를 씁니다.</li><li><strong>운영자가 숨긴 질문</strong>: 그 시즌의 다른 질문은 풀에 있는데 그날 질문만 없으면 숨긴 것으로 보고, 그날은 기본 순환 질문을 보입니다(슬픈 일이 있는 날, <code>reviewQuestion</code> hide). 시즌 질문을 <strong>모두</strong> 숨기면 시드 전과 구별할 수 없어 앱 안 사본이 나옵니다(알려진 한계). → <a href="/grato-docs/decisions#adr-35">ADR-35</a></li><li><strong>다른 질문</strong>: 지금처럼 풀 전체입니다. 시드된 시즌 질문도 들어 있어 2/1에 숨길 때까지 나옵니다. 기본 순환(시즌 밖의 그날 질문)에는 시즌 질문을 넣지 않아, 시드해도 순서가 밀리지 않습니다.</li><li><strong>이어지는 질문</strong>: 감사의 계절·한 해 돌아보기 질문으로 시작하면 한 해 돌아보기의 이어지는 질문 3개 중 하나(감사의 계절은 <code>followupFrom: &quot;2026-winter&quot;</code>)(&quot;그 순간을 떠올리면 지금 어떤 마음이 드나요?&quot; 등). 신년 질문과 그 밖에는 기본 이어지는 질문. 두 번째 질문의 &quot;다른 질문&quot;은 풀 전체.</li><li><strong>나만 보기 그대로</strong>: 시즌 질문으로 써도 기본은 나만 보기, Circle은 미리 고르지 않습니다(ADR-12). 시즌 문구에 &quot;나눠 보세요&quot;를 넣지 않습니다.</li><li><strong>위젯</strong>: 앱이 7일 치 질문을 같은 함수로 계산해 요약본에 넣으므로, 앱을 며칠 열지 않아도 시즌 첫날부터 위젯에 시즌 질문이 나옵니다. Swift·Java 위젯은 날짜별 질문을 보여 주기만 해 바꾸지 않았습니다.</li><li><strong>예전 앱(1.0.1 (4) 이하)</strong>: 시즌 계산이 없어 그날의 질문은 기본 순환입니다. 시드된 시즌 질문은 풀에 들어가 &quot;다른 질문&quot;과 날짜 순환에서 만납니다(순환 순서는 바뀜).</li><li><strong>미리 보기</strong>: 개발 빌드의 <a href="/grato-docs/mobile/#dev-clock">테스트 날짜</a>로 11/15·12/1·12/28·1/1·2/1을 봅니다.</li></ul><h3 id="server-seasons" tabindex="-1">서버 시즌 (관리자에서 만들기·게시) <a class="header-anchor" href="#server-seasons" aria-label="Permalink to &quot;서버 시즌 (관리자에서 만들기·게시) {#server-seasons}&quot;">​</a></h3><p>앱 업데이트 없이 시즌을 더하거나 고칩니다(앱 1.0.1 (7)부터). 운영자가 관리자 › <strong>시즌</strong>에서 <a href="/grato-docs/architecture/data-model#seasons">서버 시즌 문서</a>를 만들고 게시하면, 앱이 다음에 열릴 때 그 시즌으로 그날의 질문·이어지는 질문·위젯·매일 알림 문구를 계산합니다. → <a href="/grato-docs/decisions#adr-41">ADR-41</a>, <a href="/grato-docs/operations/deploy#server-seasons">운영 절차</a></p><ul><li><p><strong>읽기</strong>: <code>src/lib/seasonApi.js</code>의 <code>loadSeasons()</code>가 <code>seasons</code>를 <code>status in [&#39;published&#39;, &#39;ended&#39;]</code>로 세션에 한 번 읽습니다(최대 50개). 질문 풀을 읽을 때(<code>loadQuestionPools</code>) 함께 기다리되 같은 4초 제한 안에서이고, 시작을 막지 않습니다(ADR-13). 실패·오프라인 캐시 결과는 기억하지 않아 다음에 다시 읽습니다.</p></li><li><p><strong>합치기</strong>: <code>seasonQuestions.js</code>의 <code>applyServerSeasons(docs)</code> → <code>mergeSeasons(BUNDLED_SEASONS, docs)</code>. 게시된 문서는 같은 키의 앱 안 시즌을 대신하거나 새로 더하고, 끝난 문서는 그 키를 뺍니다. 날짜·키가 맞지 않는 문서(<code>isRunnableSeason</code>)와 초안은 무시합니다(앱 안 시즌 그대로). <code>SEASONS</code>·<code>SEASON_QUESTIONS</code>는 바뀌는 값(<code>export let</code>)이라 <code>questionForDay</code> 등 기존 함수가 그대로 씁니다.</p></li><li><p><strong>문구</strong>: 게시하면 서버가 시즌 질문 문서(<code>system_season_*</code>)도 씁니다. 그래서 그날 질문은 지금처럼 풀의 사본이 있으면 그것을, 없으면 시즌 문서의 문구를 보입니다. 질문 탭에서 그날 질문만 숨기면 그날은 기본 순환(지금과 같음).</p></li><li><p><strong>예전 앱</strong>: 1.0.1 (5)는 서버 시즌을 모릅니다. 새 키의 시즌 질문은 &quot;다른 질문&quot;에만, 앱 안 시즌을 서버에서 고친 경우는 문구(같은 문서 ID)만 반영되고 날짜·순서는 앱 안 그대로입니다.</p></li><li><p><strong>넣기·숨기기</strong>: <a href="/grato-docs/operations/deploy#season-questions">배포: 시즌 질문</a></p></li></ul><h2 id="길이-제한" tabindex="-1">길이 제한 <a class="header-anchor" href="#길이-제한" aria-label="Permalink to &quot;길이 제한&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>제한</th></tr></thead><tbody><tr><td>답변 하나</td><td>1000자 (두 답변과 빈 줄을 합쳐도 내용 한도 안)</td></tr><tr><td>제목</td><td>1~100자 (화면에서 필수, 규칙은 0~100자)</td></tr><tr><td>내용</td><td>1~3000자</td></tr></tbody></table><h2 id="분석-이벤트" tabindex="-1">분석 이벤트 <a class="header-anchor" href="#분석-이벤트" aria-label="Permalink to &quot;분석 이벤트&quot;">​</a></h2><table tabindex="0"><thead><tr><th>이벤트</th><th><code>props</code></th></tr></thead><tbody><tr><td><code>gratitude_started</code></td><td>질문으로 쓰기: <code>{ mode: &#39;guided&#39;, source, seasonKey? }</code> (<code>source</code>: <code>&#39;write_page&#39;</code> 카드의 [이 질문으로 감사 적기], <code>&#39;widget&#39;</code> 위젯. <code>seasonKey</code>는 시즌 질문일 때만). 직접 작성: <code>{ mode: &#39;manual&#39; }</code> — 쓰기 화면이 바로 직접 작성이라 제목이나 내용을 처음 입력할 때 한 번</td></tr><tr><td><code>gratitude_created</code></td><td><code>{ mode: &#39;guided&#39;, hasGroup }</code></td></tr><tr><td><code>question_submitted</code></td><td><code>{ kind }</code> — 질문 제안 성공</td></tr></tbody></table><h2 id="화면-문구" tabindex="-1">화면 문구 <a class="header-anchor" href="#화면-문구" aria-label="Permalink to &quot;화면 문구&quot;">​</a></h2><p>질문으로 쓰기의 문구는 &quot;질문&quot;, &quot;답변&quot;, &quot;초안&quot;으로 기능을 설명합니다. 사용자에게 보이는 문구에는 &quot;AI&quot;나 &quot;인공지능&quot;이라는 표현을 쓰지 않습니다.</p>',31))])}const m=r(q,[["render",h]]);export{b as __pageData,m as default};
